INSERT IGNORE INTO `classes` (`subject_id`, `kind`, `name`) SELECT DISTINCT `subject_id`, `role`, CASE `role` WHEN 'wyklad' THEN 'Wykład' WHEN 'laboratorium' THEN 'Laboratorium' WHEN 'cwiczenia' THEN 'Ćwiczenia' WHEN 'projekt' THEN 'Projekt' END FROM `subject_lecturers`;--> statement-breakpoint
INSERT INTO `class_lecturers` (`class_id`, `lecturer_id`, `group_id`) SELECT DISTINCT `c`.`id`, `sl`.`lecturer_id`, NULL FROM `subject_lecturers` `sl` JOIN `classes` `c` ON `c`.`subject_id` = `sl`.`subject_id` AND `c`.`kind` = `sl`.`role` WHERE NOT EXISTS (SELECT 1 FROM `class_lecturers` `x` WHERE `x`.`class_id` = `c`.`id` AND `x`.`lecturer_id` = `sl`.`lecturer_id` AND `x`.`group_id` IS NULL);--> statement-breakpoint
DROP VIEW IF EXISTS `v_subject_lecturers`;--> statement-breakpoint
DROP TABLE IF EXISTS `subject_lecturers`;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_classes` AS SELECT `id`, `subject_id`, `kind`, `name` FROM `classes`;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_class_groups` AS SELECT `id`, `class_id`, `number`, `name` FROM `class_groups`;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_class_lecturers` AS SELECT `class_id`, `lecturer_id`, `group_id` FROM `class_lecturers`;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_topics` AS SELECT `id`, `subject_id`, `class_id`, `group_id`, `title`, `discord_thread_id`, `created_by`, `created_at` FROM `topics` WHERE `deleted_at` IS NULL;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_files` AS SELECT `m`.`id` AS `material_id`, `s`.`code` AS `subject_code`, `s`.`name` AS `subject_name`, `c`.`name` AS `class_name`, `g`.`name` AS `group_name`, `t`.`id` AS `topic_id`, `t`.`title` AS `topic_title`, `m`.`original_filename` AS `filename`, `m`.`mime_type` AS `mime_type`, `m`.`size_bytes` AS `size_bytes`, `m`.`preview_kind` AS `preview_kind`, `m`.`status` AS `status`, `u`.`display_name` AS `uploader`, `m`.`created_at` AS `created_at` FROM `materials` `m` JOIN `topics` `t` ON `t`.`id` = `m`.`topic_id` AND `t`.`deleted_at` IS NULL JOIN `subjects` `s` ON `s`.`id` = `t`.`subject_id` LEFT JOIN `classes` `c` ON `c`.`id` = `t`.`class_id` LEFT JOIN `class_groups` `g` ON `g`.`id` = `t`.`group_id` LEFT JOIN `users` `u` ON `u`.`id` = `m`.`uploader_id` WHERE `m`.`deleted_at` IS NULL;
